arguments.new_str:
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainerService>();

// Train the model before building the app so the model file exists for the pool
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

var data = mlContext.Data.LoadFromTextFile<TicketInput>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject))
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
    .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

var model = pipeline.Fit(split.TrainSet);

var predictions = model.Transform(split.TestSet);
var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");
Console.WriteLine("===== Model Evaluation Metrics =====");
Console.WriteLine($"  MicroAccuracy:    {metrics.MicroAccuracy:P2}");
Console.WriteLine($"  MacroAccuracy:    {metrics.MacroAccuracy:P2}");
Console.WriteLine($"  LogLoss:          {metrics.LogLoss:F4}");
Console.WriteLine($"  LogLossReduction: {metrics.LogLossReduction:F4}");
Console.WriteLine("====================================");

mlContext.Model.Save(model, data.Schema, modelPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

